const fs=require('node:fs'),{chromium}=require('playwright');fs.mkdirSync('qa-output/registration',{recursive:true});(async()=>{const b=await chromium.launch({headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']}),p=await b.newPage({viewport:{width:768,height:768}}),errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('console',m=>{if(m.type()==='error')console.error(m.text())});await p.goto('http://127.0.0.1:8765/qa/registration.html');await p.waitForFunction(()=>window.probeReady,null,{timeout:120000});for(const variant of['neutral','jawOpen'])for(const name of['gnm','anny','mhr']){const q=await p.evaluate(([name,variant])=>window.registrationProbe.inspect(name,variant),[name,variant]);const suffix=variant==='neutral'?'':'-'+variant;fs.writeFileSync('qa-output/registration/'+name+suffix+'.json',JSON.stringify(q,null,2));await p.screenshot({path:'qa-output/registration/'+name+suffix+'.png'});console.log(name,q.detected,'landmarks',q.landmarks.filter(x=>x.hit).length,'ray hits');}fs.writeFileSync('qa-output/registration/errors.json',JSON.stringify(errors));await b.close();})().catch(e=>{console.error(e);fs.writeFileSync('qa-output/registration/failure.txt',String(e.stack));process.exit(1)});
